// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and initialize the contract
        // First call initialize: credChainId_=1, credId_=1, verificationType_="test", protocolFeeDestination_=address(this)
        // The initialize sets the initial owner to msg.sender (this contract via Test)
        c.initialize(1, 1, "test", address(this));

        // Record initial owner (this contract)
        address initialOwner = c.owner();

        // Prepare a new owner address (a random address)
        address newOwner = address(0x1234);

        // Transfer ownership to newOwner (onlyOwner, msg.sender is the current owner)
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // New owner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // After acceptance, P.owner() returns newOwner (0x1234), M.owner() returns address(0) because it reads slot 0
        address actualOwner = c.owner();

        // Assert that the owner is the newOwner (this holds for P, fails for M)
        assertTrue(actualOwner == newOwner);
    }
}

