pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and initialize the contract via the proxy pattern (UUPS)
        // In Foundry, we can deploy a minimal proxy or directly call initialize.
        // But C is not an upgradeable proxy in the test; we can call initialize directly.
        // The test must ensure the contract is in a state where paused() can be called.
        // Since the difference is in paused() itself (inverted return), we don't need any special state.
        // However, the function paused() is public and returns the value of the storage slot.
        // The test will compare the return value of c.paused() with the expected value (false).
        // For the reference P, paused() returns the actual stored boolean; for M, it returns the negation.
        // We will initialize the contract (which sets _paused to false) and then call acceptOwnership() 
        // (which does not change the pause state) and then assert that paused() returns false.

        // Initialize the contract with required parameters
        uint256 credChainId = 1;
        uint256 credId = 1;
        string memory verificationType = "signature";
        address protocolFeeDestination = address(0xdead);

        // We need to call initialize via the proxy. Since C is deployed directly, we can call initialize.
        // But note: initialize has the initializer modifier; calling it on a fresh deployment should work.
        c.initialize(credChainId, credId, verificationType, protocolFeeDestination);

        // Now acceptOwnership from the owner (address(this) is the owner after __Ownable_init)
        c.acceptOwnership();

        // The pause state is still false (initialized to false, never changed).
        // In the reference contract, paused() returns false.
        // In the mutated contract, paused() returns true.
        // Assert that paused() returns false (the correct behavior).
        assertTrue(c.paused() == false);
    }
}

