        (uint256 bps, address recipient) = c.getRoyalties(0);

        // The default config in P has royaltyRecipient = address(0) (the initialized recipient),
        // but in M it is address(1). However after looking at the code more carefully:
        // P's getRoyalties returns: RoyaltyConfiguration({ royaltyBPS: 500, royaltyRecipient: royaltyRecipient })
        // where royaltyRecipient is the storage variable set by initializeRoyalties
        // M returns: RoyaltyConfiguration({ royaltyBPS: 500, royaltyRecipient: address(1) })
