    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Create a new owner who will accept ownership of the contract
        address newOwner = address(0x1234);

        // Transfer ownership to the new owner
        c.transferOwnership(newOwner);

        // Have the new owner accept ownership – this triggers a call sequence
        // that ends with acceptOwnership().
        vm.prank(newOwner);
        c.acceptOwnership();

        // Now the contract has been initialized (via the initializer in setUp),
        // which calls initializeRoyalties with the deployer (address(this)).
        // The default royalty recipient is set to address(this).
        // Now call getRoyalties for a token (0) that has no per-token override.
        // In P (correct): returns RoyaltyConfiguration(500, address(this))
        // In M (bug): returns RoyaltyConfiguration(1000, address(this))
        (uint32 bps, address recipient) = c.getRoyalties(0);

        // Assert that the basis points are 500 (the correct value).
        // The buggy version would return 1000, so this assertion fails on M.
        assertTrue(bps == 500, "Expected default royaltyBPS to be 500");
    }
}

