import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Prepare addresses
        address defaultRecipient = address(0x1234);
        address overrideRecipient = address(0x5678);
        uint256 tokenId = 1;

        // Initialize royalties with a default recipient (simulate initialization)
        // Directly call the internal function through a wrapper not available, so we use the available external methods.
        // The only way to set royalties is via updateRoyalties, but that requires being owner or art creator.
        // Since we need to test getRoyalties, we must first set up a state where initilaized is true and a token has an override.
        // We can call the initialize function which sets initilaized=true via initializeRoyalties(protocolFeeDestination_).
        // But that also initializes other state. We'll use the public initialize with a dummy cred chain.
        vm.prank(address(this)); // owner will be this contract
        c.initialize(1, 1, "test", defaultRecipient);
        // Now initilaized is true, default royalty is 500 BPS to defaultRecipient.

        // Set a royalty override for tokenId with a non-zero recipient
        // We need to be the owner to call updateRoyalties (since onlyArtCreator checks artist or owner).
        // But the contract has no explicit getter for the override we set, so we update and then check getRoyalties.
        // We need to create an art first to have a tokenId. Use createArtFromFactory which is onlyPhiFactory.
        // Instead, we can directly set the override via updateRoyalties which requires onlyArtCreator.
        // Since we are not the artist, we become owner (we deployed as owner).
        // The onlyArtCreator modifier checks msg.sender != artist && msg.sender != owner().
        // Since we are owner, we can call updateRoyalties.
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = 
            ICreatorRoyaltiesControl.RoyaltyConfiguration(1000, overrideRecipient);
        vm.prank(address(this)); // owner
        c.updateRoyalties(tokenId, config);

        // Now call getRoyalties(tokenId)
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory result = c.getRoyalties(tokenId);
        bool overrideReturned = (result.royaltyRecipient == overrideRecipient);
        assertTrue(overrideReturned);
    }
