        // Now simulate a factory call: we need to send enough ETH to cover artCreateFee (which may be zero)
        // We'll directly call createArtFromFactory as onlyPhiFactory; we can use vm.prank with the contract's own address
        // Since phiFactoryContract is set to msg.sender in initialize, we prank as that sender
        address factory = address(this);
