        // We'll use vm.prank to call as factory
        vm.prank(factory);
        c.claimFromFactory{value: 0}(1, address(this), address(0), address(0), 1, bytes32(0), "");
        // Now check balance
        uint256 bal = c.balanceOf(address(this), 1);
        assertTrue(bal == 1);
    }
}

